import type { ClientReceiptStatus, DeductionSummary } from './receipt.port';

export type InvoiceStatus = 'DRAFT' | 'ISSUED' | 'FINALIZED' | 'VOID' | 'CONVERTED';
export type InvoiceKind = 'REGULAR' | 'PROFORMA';
export type InvoiceMilestoneType = 'CAPEX' | 'OPEX';

/** DocumentLink.linkType value used to mark an invoice's uploaded client
 * acknowledgment ("inward copy") — distinguishes it, on the same INVOICE
 * entityType, from a plain unlabelled supporting document (docs/04 §11.4:
 * "primary tax invoice PDF is generated by CRM; inward acknowledgment
 * remains uploadable"). */
export const INVOICE_INWARD_COPY_LINK_TYPE = 'INWARD_COPY';

export interface InvoiceLineInput {
  description: string;
  hsnSac: string | undefined;
  quantity: string;
  unitPrice: string;
  gstRatePercent: string;
  /** CAPEX event this line bills. Omitted on OPEX and on a single-event invoice. */
  sourceEventId?: string;
}

export interface InvoiceLineSummary {
  id: string;
  sequence: number;
  description: string;
  hsnSac: string | null;
  sourceEventId: string | null;
  quantity: string;
  unitPrice: string;
  taxableAmount: string;
  gstRatePercent: string;
  cgstAmount: string;
  sgstAmount: string;
  igstAmount: string;
  lineTotal: string;
}

/**
 * What was billed and what came back against a finalized invoice, or against
 * one milestone event's or installment's share of it (ADR-155). Every figure
 * is derived live from posted receipts, releases and finalized credit/debit
 * notes; nothing here is stored. docs/04 §11.5: invoice total, cash received,
 * TDS/GST-TDS, recoverable deductions, penalties and true outstanding are
 * shown separately.
 */
export interface InvoiceCollection {
  invoiceTotal: string;
  /** Finalized debit notes minus finalized credit notes. */
  creditDebitNet: string;
  received: string;
  tds: string;
  /** CGST + SGST + IGST TDS. */
  gstTds: string;
  hold: string;
  retention: string;
  /** Accepted plus disputed penalties. */
  penalty: string;
  otherDeductions: string;
  /** Hold and retention paid back later. */
  released: string;
  /** Hold plus retention still to be released. */
  holdRetentionPending: string;
  /** invoiceTotal + creditDebitNet - received - every deduction. */
  outstanding: string;
}

/** One posted or reversed receipt allocation on an invoice, with its deductions. */
export interface InvoiceReceiptAllocation {
  allocationId: string;
  receiptId: string;
  receiptDate: string;
  receiptStatus: ClientReceiptStatus;
  utrReference: string | null;
  /** The one event this allocation pays on a multi-event invoice (ADR-151); null = whole invoice. */
  sourceEventId: string | null;
  sourceEventName: string | null;
  cashAllocated: string;
  settledAmount: string;
  deductions: DeductionSummary[];
}

/** One finalized invoice's share billed against one CAPEX event or OPEX installment. */
export interface InvoiceSourceShare {
  invoiceId: string;
  invoiceNumber: string | null;
  invoiceDate: string | null;
  /** The period the invoice bills (OPEX installments); null for a CAPEX event. */
  servicePeriodStart: string | null;
  servicePeriodEnd: string | null;
  /** Taxable amount this invoice billed against the source. */
  billedTaxable: string;
  collection: InvoiceCollection;
}

/** Every finalized invoice that billed one CAPEX event or OPEX installment. */
export interface InvoiceSourceBilling {
  sourceId: string;
  billedTaxable: string;
  collection: InvoiceCollection;
  invoices: InvoiceSourceShare[];
}

export interface InvoiceSummary {
  id: string;
  projectId: string;
  projectName: string;
  legalEntityId: string;
  legalEntityName: string;
  gstRegistrationId: string;
  gstRegistrationGstin: string;
  paymentAlertId: string;
  milestoneType: InvoiceMilestoneType;
  sourceEventId: string | null;
  sourceInstallmentId: string | null;
  sourceTitle: string;
  status: InvoiceStatus;
  kind: InvoiceKind;
  invoiceNumber: string | null;
  proformaNumber: string | null;
  invoiceDate: string | null;
  dueDate: string | null;
  paymentTermsDays: number | null;
  servicePeriodStart: string | null;
  servicePeriodEnd: string | null;
  taxableAmount: string | null;
  cgstAmount: string | null;
  sgstAmount: string | null;
  igstAmount: string | null;
  totalAmount: string | null;
  /** totalAmount minus the sum of non-reversed receipt allocations settled
   * against this invoice — computed live in list(), never persisted (same
   * pattern as ReceiptsService/PaymentAlertsService outstanding figures).
   * null when totalAmount itself is null (draft, not yet finalized). */
  outstandingAmount: string | null;
  /** Money billed and collected. Null unless FINALIZED. */
  collection: InvoiceCollection | null;
  /** True when at least one document is linked to this invoice with
   * linkType === INVOICE_INWARD_COPY_LINK_TYPE — computed live in list()/
   * getDetail() via the documents module, never persisted (same
   * live-computed pattern as outstandingAmount). */
  hasInwardCopy: boolean;
  narrative: string | null;
  journalEntryId: string | null;
  voidJournalEntryId: string | null;
  voidReason: string | null;
  voidedBy: string | null;
  voidedAt: string | null;
  version: number;
}

export interface InvoiceDetail extends InvoiceSummary {
  sellerLegalName: string | null;
  sellerPan: string | null;
  sellerGstin: string | null;
  sellerState: string | null;
  sellerAddress: string | null;
  buyerName: string | null;
  buyerGstin: string | null;
  buyerState: string | null;
  buyerAddress: string | null;
  lines: InvoiceLineSummary[];
  /** Receipt allocations on this invoice, newest first, reversed ones included. */
  receipts: InvoiceReceiptAllocation[];
  /** On a draft: taxable amount billed beyond what is left on its event(s) or installment; null otherwise (ADR-165). */
  overBilledBy: string | null;
  /** On a draft: taxable amount it bills short of what is left on its source(s); null otherwise (ADR-167). */
  underBilledBy: string | null;
  /** Finalized as the full bill for its source(s): nothing more is expected on them (ADR-167). */
  completesSource: boolean;
  /** Set when this tax invoice was opened from a proforma, or this proforma has a tax invoice. */
  convertedFromInvoiceId: string | null;
  convertedFromProformaNumber: string | null;
  convertedToInvoiceId: string | null;
  convertedToInvoiceNumber: string | null;
  convertedToStatus: InvoiceStatus | null;
  /** Lines from the previous OPEX invoice on this schedule. Null for CAPEX, and when none exists. */
  previousOpexLabel: string | null;
  previousOpexLines: Array<{ description: string; hsnSac: string | null; unitPrice: string; gstRatePercent: string }> | null;
}

/** Another open CAPEX event on the same project that can share this invoice. */
export interface InvoiceCapexChoice {
  paymentAlertId: string;
  sourceEventId: string;
  description: string;
  taxableAmount: string;
}

export interface InvoiceDraftDefaults {
  paymentAlertId: string;
  sourceEventId: string | null;
  projectId: string;
  legalEntityId: string;
  legalEntityName: string;
  gstRegistrationOptions: Array<{ id: string; gstin: string; tradeName: string | null }>;
  /** Active bank accounts of the project's legal entity. More than one means the creator must choose. */
  bankAccountOptions: Array<{
    id: string;
    accountName: string;
    bankName: string | null;
    maskedAccountNumber: string | null;
    invoiceAccountNumber: string | null;
    ifsc: string | null;
  }>;
  milestoneType: InvoiceMilestoneType;
  suggestedDescription: string;
  /** What is still to invoice on the source: its amount less what finalized invoices billed (ADR-156). */
  suggestedTaxableAmount: string;
  /** The event's amount or the installment's scheduled amount. */
  sourceAmount: string;
  /** Taxable amount already billed on this source by finalized invoices. */
  invoicedAmount: string;
  servicePeriodStart: string | null;
  servicePeriodEnd: string | null;
  buyerName: string;
  buyerGstin: string | null;
  buyerState: string | null;
  buyerAddress: string | null;
  /** Empty for OPEX. Other open CAPEX events on this project. */
  capexChoices: InvoiceCapexChoice[];
  /** Lines from the previous OPEX invoice on this schedule. Null for CAPEX, and when none exists. */
  previousOpexLabel: string | null;
  previousOpexLines: Array<{ description: string; hsnSac: string | null; unitPrice: string; gstRatePercent: string }> | null;
}

export interface InvoiceFilters {
  projectId?: string | undefined;
  status?: InvoiceStatus | undefined;
  legalEntityId?: string | undefined;
}

export interface InvoicePort {
  /** Pre-fills the add-form from the PaymentAlert being raised — docs/04
   * §11.4: "milestone/installment is preselected from alert where
   * applicable." */
  getDraftDefaults(input: {
    organizationId: string;
    paymentAlertId: string;
    actorId: string;
    canSeeAll: boolean;
  }): Promise<InvoiceDraftDefaults>;

  /** The only creation path — docs/04 §11.4: "remove free ad-hoc invoice
   * creation." Rejects if the alert is already CLOSED or an active
   * (non-void) invoice already exists for its source. */
  createDraftFromAlert(input: {
    organizationId: string;
    paymentAlertId: string;
    gstRegistrationId: string;
    /** Required when the legal entity has more than one active bank account. */
    bankAccountId?: string;
    dueDate: string;
    paymentTermsDays: number | undefined;
    narrative: string | undefined;
    lines: InvoiceLineInput[];
    /** Further CAPEX alerts to bill on this same invoice. Rejected for OPEX. */
    additionalPaymentAlertIds?: string[];
    /** Omitted means a regular tax invoice. */
    kind?: InvoiceKind;
    idempotencyKey: string;
    actorId: string;
    correlationId: string;
  }): Promise<InvoiceSummary>;

  /** Only reachable while status is DRAFT — docs/03: "Draft invoices are
   * editable." */
  updateDraft(input: {
    organizationId: string;
    id: string;
    expectedVersion: number;
    gstRegistrationId: string | undefined;
    dueDate: string | undefined;
    paymentTermsDays: number | undefined;
    narrative: string | undefined;
    lines: InvoiceLineInput[] | undefined;
    kind?: InvoiceKind;
    actorId: string;
    correlationId: string;
  }): Promise<InvoiceSummary>;

  /** Opens a regular tax-invoice draft copied from an issued proforma.
   * The proforma becomes CONVERTED and stays printable. Nothing is posted
   * until that draft is finalized. A second call returns the open draft. */
  startConversion(input: {
    organizationId: string;
    id: string;
    expectedVersion: number;
    idempotencyKey: string;
    actorId: string;
    correlationId: string;
  }): Promise<InvoiceSummary>;

  /** Snapshots seller/buyer, generates the invoice number (scoped to GST
   * registration + financial year), posts the docs/06 "Finalize client
   * invoice" journal, and closes the source PaymentAlert. Rejects if the
   * CAPEX milestone's total finalized invoice value would exceed its
   * approved amount (docs/01). Immutable afterward. `invoiceNumber`, when
   * given, is used instead of the generated number; it must be unused in
   * that GST registration and financial year, except by a voided invoice
   * (ADR-163). A financial year missing for `invoiceDate` is created
   * (ADR-150). */
  finalize(input: {
    organizationId: string;
    id: string;
    expectedVersion: number;
    invoiceDate: string;
    invoiceNumber?: string | undefined;
    completesSource?: boolean | undefined;
    idempotencyKey: string;
    actorId: string;
    correlationId: string;
  }): Promise<InvoiceSummary>;

  /** Marks a FINALIZED invoice as the full bill for its source(s), or undoes
   * it; the installment status and the alert follow (ADR-167). Posts nothing. */
  setCompletesSource(input: {
    organizationId: string;
    id: string;
    completesSource: boolean;
    expectedVersion: number;
    actorId: string;
    correlationId: string;
  }): Promise<InvoiceSummary>;

  /** Voided invoice numbers this draft may take, for the GST registration
   * and financial year of `invoiceDate`, that no other invoice holds now
   * (ADR-163). */
  reusableNumbers(input: { organizationId: string; id: string; invoiceDate: string }): Promise<string[]>;

  /** A DRAFT voids with a simple status flip. A FINALIZED invoice voids
   * by calling PostingService.reverseJournal against the finalize
   * posting (Slice 4.6, reused as-is) and reopens the source
   * PaymentAlert. `accountingDate` is required only when voiding a
   * FINALIZED invoice (the reversal's own posting date). A FINALIZED
   * invoice's posted receipts are reversed first on that date, which needs
   * `canReverseReceipts` (receipt.reverse); a receipt that also pays another
   * invoice, or has a released hold or retention, blocks the void (ADR-164). */
  void(input: {
    organizationId: string;
    id: string;
    expectedVersion: number;
    reason: string;
    accountingDate: string | undefined;
    canReverseReceipts: boolean;
    idempotencyKey: string;
    actorId: string;
    correlationId: string;
  }): Promise<InvoiceSummary>;

  list(input: {
    organizationId: string;
    page: number;
    pageSize: number;
    filters: InvoiceFilters;
    actorId: string;
    canSeeAll: boolean;
  }): Promise<{ rows: InvoiceSummary[]; total: number }>;

  getDetail(input: { organizationId: string; id: string; actorId: string; canSeeAll: boolean }): Promise<InvoiceDetail>;

  /** Each CAPEX event and OPEX installment of a project with the finalized
   * invoices that billed it and what was collected on its share (ADR-155).
   * A whole-invoice amount on a multi-event invoice is split across its
   * events by their line totals. */
  listBySource(input: { organizationId: string; projectId: string; actorId: string; canSeeAll: boolean }): Promise<InvoiceSourceBilling[]>;

  /** Rendered on demand from current stored data (draft or finalized) —
   * no PDF file is ever persisted (ADR-068 decision 10). */
  getPdf(input: { organizationId: string; id: string; actorId: string; canSeeAll: boolean }): Promise<{ filename: string; base64: string }>;
}
